const e = $('Entree').first().json;
const fiche = $('Fiche code').first().json.fiche;
let hist = 'Client non precise : pas d historique.';
try {
  const h = String($('Historique client').first().json.resultat || '');
  if (h) hist = h.split('\n').filter(l => !/^(Contact|Adresse) :/.test(l)).join('\n');
} catch (x) {}
const t = [
  'Marque : ' + (e.marque || 'inconnue'),
  'Modele lu sur la plaque : ' + (e.modele || 'inconnu'),
  'Code affiche : ' + (e.code || 'aucun'),
  'Symptomes decrits par le technicien : ' + (e.symptomes || 'aucun detail'),
  '',
  'FICHE OFFICIELLE DU CODE ET NOTES TERRAIN :',
  fiche,
  '',
  'HISTORIQUE CLIENT :',
  hist
].join('\n');
return [{ json: { contexte: t } }];

const i = $input.first().json || {};
const modele = String(i.modele || '').toUpperCase().replace(/\s+/g, '').trim();
let marque = String(i.marque || '').trim();
if (/^tosh/i.test(marque)) marque = 'Toshiba';
else if (/^daik/i.test(marque)) marque = 'Daikin';
if (!marque && /^(RAS|RAV|MMY|MCY|MM[A-Z]|HWT|HWS)-?/.test(modele)) marque = 'Toshiba';
if (!marque && /^(FTX|ATX|ARX|CTX|FVX|FDX|RX[A-Z]|FBA|FCA|FFA|FHA|AZA|RZA|RZQ|FX[A-Z]|REY|RYY|RXY|EH[A-Z]|ER[A-Z]|EB[A-Z]|ED[A-Z])/.test(modele)) marque = 'Daikin';
const code = String(i.code || '').toUpperCase().replace(/^(CODE|ERREUR|ERROR)\s*/, '').replace(/[-_.]+/g, ' ').replace(/\s+/g, ' ').trim();
return [{ json: { marque, modele, code, cle: code.replace(/[^A-Z0-9]/g, ''), symptomes: String(i.symptomes || '').slice(0, 2000), client_id: String(i.client_id || '').trim() } }];

const e = $('Entree').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.code_cle);
let fiche = '';
if (!e.cle) fiche = 'Aucun code defaut fourni.';
else if (!rows.length) fiche = 'Pas de base de codes defaut pour la marque ' + (e.marque || 'inconnue') + '.';
else {
  const sp = s => String(s || '').toUpperCase().replace(/\s+/g, ' ').trim();
  const exact = rows.filter(r => r.code_cle === e.cle);
  const sous = rows.filter(r => r.code_cle !== e.cle && sp(r.code).startsWith(e.code + ' ')).slice(0, 10);
  const v = new Set();
  const m = /^E?0*(\d{1,3})$/.exec(e.cle);
  if (m) { const n = m[1]; const p2 = n.padStart(2, '0'); [n, p2, 'E' + p2, 'E' + n, n.padStart(4, '0')].forEach(x => v.add(x)); }
  const proches = rows.filter(r => v.has(r.code_cle) && r.code_cle !== e.cle);
  const f = r => 'Code ' + r.code + ' : ' + r.designation + (r.notes ? ' | Consignes Toshiba : ' + r.notes : '') + (r.notes_climatpro ? ' | Note terrain ClimatPro : ' + r.notes_climatpro : '');
  const L = [];
  exact.forEach(r => L.push(f(r)));
  if (proches.length) { L.push('Meme code sous un autre affichage :'); proches.forEach(r => L.push(f(r))); }
  if (sous.length) { L.push('Sous-codes existants :'); sous.forEach(r => L.push(f(r))); }
  fiche = L.length ? L.join('\n') : 'Code ' + e.code + ' absent de la base officielle ' + e.marque + '.';
}
return [{ json: { fiche } }];

const r = $input.first().json || {};
let t = String(r.text || '').trim();
if (!t) t = 'Expert diagnostic indisponible pour le moment' + (r.error ? ' (' + String(r.error).slice(0, 200) + ')' : '') + '. Utilise la fiche du code defaut.';
t = t.replace(/\*\*/g, '').replace(/[\u2013\u2014]/g, '-');
return [{ json: { resultat: 'Analyse de l expert diagnostic (Sonnet) :\n' + t } }];
